/** Записи блога: заголовок, подводка, содержимое. */
function artdom_demo_posts() {
	return array(
		array(
			'title'   => 'Семь документов, которые смотрят до задатка',
			'excerpt' => 'Выписка из ЕГРН — только первый из них. Разбираем, что запрашивать у продавца и на что смотреть в каждой бумаге.',
			'content' => "<p>Задаток вносится до сделки и почти никогда не возвращается полностью. Поэтому проверку делают до него, а не после — иначе торг за возврат идёт уже с чужой позиции.</p>
<h2>Что запрашиваем</h2>
<p>Выписка из ЕГРН об объекте и о переходе прав, документ-основание, справка об отсутствии долгов по коммунальным платежам, технический паспорт, согласие супруга, справка о зарегистрированных и разрешение опеки, если в собственниках есть несовершеннолетний.</p>
<h2>На что смотреть</h2>
<p>В выписке о переходе прав важна не последняя запись, а частота смен собственника. Три перехода за два года — повод разбираться дальше, даже если каждый из них по бумагам чист.</p>
<p>Технический паспорт сверяем с тем, что видим на показе. Несогласованная перепланировка не всегда препятствие для сделки, но всегда предмет для торга.</p>"
		),
		array(
			'title'   => 'Клубный дом и башня: разница, которую видно через год',
			'excerpt' => 'Число квартир на этаж, состав соседей и стоимость обслуживания — три вещи, которые в рекламе не пишут, а жить с ними придётся.',
			'content' => "<p>В рекламе оба формата называют премиальными, и на этапе выбора они выглядят похоже. Разница проявляется не на показе, а примерно через год жизни.</p>
<h2>Сколько соседей на этаже</h2>
<p>В клубном доме на этаже две-три квартиры, в башне — восемь и больше. Это не про престиж, а про то, сколько людей пользуется вашим лифтовым холлом каждый день.</p>
<h2>Кто платит за фасад</h2>
<p>Обслуживание дорогого фасада делится на число квартир. В доме на тридцать квартир взнос на ремонт входной группы ощутим, в доме на триста — нет. Считать это надо до покупки, а не по первой квитанции.</p>"
		),
		array(
			'title'   => 'Ипотека на апартаменты: что изменилось в 2026',
			'excerpt' => 'Ставка выше, первоначальный взнос больше, а часть банков не работает с апартаментами вовсе. Разбираем, к чему готовиться.',
			'content' => "<p>Апартаменты юридически не жильё, и банки относятся к ним как к коммерческой недвижимости. Из этого следует почти всё остальное.</p>
<h2>Ставка и взнос</h2>
<p>Ставка обычно на полтора-два пункта выше, чем по квартире, первоначальный взнос — от тридцати процентов. Государственные программы поддержки на апартаменты не распространяются.</p>
<h2>Не все банки берутся</h2>
<p>Из крупных банков с апартаментами работает примерно половина, и у каждого свой список аккредитованных комплексов. Поэтому подбор банка идёт параллельно с подбором объекта, а не после него.</p>"
		),
		array(
			'title'   => 'Почему брокер приходит с двумя вариантами, а не с двадцатью',
			'excerpt' => 'Длинный список — признак не усердия, а того, что запрос не разобран. Рассказываем, из чего складывается короткий.',
			'content' => "<p>Клиент часто оценивает работу брокера по числу показанных объектов. Это понятная, но обратная мера: чем длиннее список, тем меньше в него вложено.</p>
<h2>Что происходит до показа</h2>
<p>Между запросом и первым показом лежит работа, которой клиент не видит: отсев по юридической истории, разговоры с соседями, проверка планов застройки квартала, сверка реальных цен сделок с ценами объявлений.</p>
<h2>Короткий список — это отсев</h2>
<p>Из тридцати подходящих по параметрам объектов до показа доходит два-три. Остальные отсекаются по причинам, которые на фотографиях не видны, а на показе стоили бы клиенту выходного дня.</p>"
		),
		array(
			'title'   => 'Задаток, аванс и обеспечительный платёж — три разных слова',
			'excerpt' => 'В договоре они выглядят одинаково, а при срыве сделки ведут себя по-разному. Разбираем, какое слово чего стоит.',
			'content' => "<p>Три термина в предварительном договоре читаются как синонимы, но при отказе одной из сторон приводят к разным суммам на руках.</p>
<h2>Чем они отличаются</h2>
<p>Аванс — это просто часть цены вперёд. Сделка не состоялась по любой причине — деньги возвращаются целиком. Задаток обеспечивает обязательство: отказался покупатель — теряет, отказался продавец — возвращает вдвое. Обеспечительный платёж ближе к авансу, но условия его удержания стороны пишут сами.</p>
<h2>Что смотреть в договоре</h2>
<p>Смотреть надо не заголовок документа, а формулировку в теле: суд читает существо условия, а не название. Если в тексте нет слова «задаток» и нет описания последствий отказа, деньги почти наверняка окажутся авансом.</p>
<p>Отдельно проверяем, кто именно получает деньги. Платёж риелтору или родственнику продавца не обеспечивает ничего: обязательство возникает у того, кто подписал.</p>"
		),
		array(
			'title'   => 'Перепланировка, которую придётся узаконивать',
			'excerpt' => 'Снесённая кладовка и перенесённая кухня стоят по-разному. Что банк и покупатель заметят по документам.',
			'content' => "<p>Часть изменений в квартире согласуется задним числом за месяц, часть не согласуется никогда. Разница видна ещё до показа — по техническому паспорту.</p>
<h2>Что проходит</h2>
<p>Демонтаж ненесущих перегородок, объединение санузла, перенос дверного проёма в ненесущей стене — обычно узакониваются, если не затронуты общие коммуникации и вентиляция.</p>
<h2>Что не пройдёт</h2>
<p>Кухня над жилой комнатой соседей снизу, санузел над кухней, проём в несущей стене без проекта, отопление на балконе, снос вентиляционного короба. Такую квартиру банк не возьмёт в залог, а продать её можно только со скидкой и покупателю с наличными.</p>
<p>Проверяется это сверкой плана из техпаспорта с тем, что видно на показе. Расхождение в одну стену стоит разговора с продавцом до задатка, а не после.</p>"
		),
		array(
			'title'   => 'Что смотреть в доме, кроме самого дома',
			'excerpt' => 'Категория земли, границы по межеванию и мощность на вводе решают больше, чем планировка и отделка.',
			'content' => "<p>Загородный дом покупается вместе с землёй, и половина рисков лежит именно в ней. На показе смотрят комнаты, а через год выясняется, что баня стоит на чужом участке.</p>
<h2>Земля</h2>
<p>Категория и вид разрешённого использования определяют, можно ли здесь вообще жить и прописаться. Границы должны быть отмежёваны и стоять на кадастровом учёте: без этого спор с соседом решается только судом.</p>
<h2>Коммуникации</h2>
<p>Газ по границе участка и газ, заведённый в дом, отличаются на сумму, сопоставимую с ценой автомобиля. У электричества важна не «есть или нет», а выделенная мощность: пятнадцать киловатт и пять — это разный дом.</p>
<p>Отдельно спрашиваем, кто чистит дорогу зимой и за чей счёт. Ответ «как-то сами договариваемся» означает, что в феврале вы будете договариваться тоже.</p>"
		),
		array(
			'title'   => 'Цена в объявлении и цена сделки: почему это разные числа',
			'excerpt' => 'Разрыв в премиальном сегменте доходит до пятнадцати процентов. Откуда он берётся и как его увидеть заранее.',
			'content' => "<p>Ориентироваться на соседние объявления бессмысленно: они показывают, чего хотят продавцы, а не что происходит на рынке.</p>
<h2>Откуда берётся разрыв</h2>
<p>Дорогой объект стоит в экспозиции месяцами, и цена в объявлении часто остаётся той, с которой начинали. Реальная сделка проходит ниже — иногда на пятнадцать процентов, а по неликвидным лотам и больше.</p>
<h2>Как считать</h2>
<p>Смотрим закрытые сделки в том же квартале и классе, с поправками на этаж, вид, состояние отделки и юридическую чистоту. Это данные не из открытых объявлений, и в этом вся ценность оценки.</p>
<p>Собственнику это нужно раньше, чем покупателю: завышенная цена стоит не денег, а месяцев. Объект «зависает», и в итоге продаётся дешевле, чем мог бы сразу.</p>"
		),
	);
}

