/**
 * Перевести страницу «О компании» на свой шаблон и заполнить блоки.
 *
 * Заполненное не трогаем: правки заказчика дороже наших примеров.
 *
 * @param int $page_id Идентификатор страницы.
 */
function artdom_fill_about( $page_id ) {
	if ( ! $page_id || ! function_exists( 'update_field' ) ) {
		return;
	}

	update_post_meta( $page_id, '_wp_page_template', 'templates/template-about.php' );

	$data = artdom_demo_about();

	foreach ( array( 'ab_intro_title', 'ab_intro_text', 'ab_principles_title', 'ab_path_title', 'ab_team_title', 'ab_team_lead' ) as $key ) {
		if ( ! get_field( $key, $page_id ) ) {
			update_field( 'field_artdom_' . $key, $data[ $key ], $page_id );
		}
	}

	/* Переименование прежнего заголовка. Обычная ветка выше заполняет только
	   пустое поле, поэтому смена демонстрационного текста сама по себе не
	   доезжает до уже созданной страницы. Меняем ровно старое значение —
	   если заказчик вписал своё, оно останется. */
	if ( 'Кто с вами будет работать' === get_field( 'ab_team_title', $page_id ) ) {
		update_field( 'field_artdom_ab_team_title', 'Команда', $page_id );
	}
	if ( 'Как мы к этому пришли' === get_field( 'ab_path_title', $page_id ) ) {
		update_field( 'field_artdom_ab_path_title', 'Хроника', $page_id );
	}
	if ( 'Три вещи, на которых всё держится' === get_field( 'ab_principles_title', $page_id ) ) {
		update_field( 'field_artdom_ab_principles_title', 'Почему мы', $page_id );
	}
	/* Принципов стало шесть: блок построен как сетка плиток по референсу, и
	   три штуки оставляли половину ряда пустой. Дополняем ТОЛЬКО прежнюю
	   тройку — если заказчик правил список сам, он останется как есть. */
	$artdom_pr = get_field( 'ab_principles', $page_id );
	if ( is_array( $artdom_pr ) && 3 === count( $artdom_pr ) ) {
		update_field(
			'field_artdom_ab_principles',
			array_map(
				static function ( $p ) {
					return array( 'field_artdom_pr_title' => $p[0], 'field_artdom_pr_text' => $p[1] );
				},
				$data['ab_principles']
			),
			$page_id
		);
	}

	if ( ! get_field( 'ab_principles', $page_id ) ) {
		update_field(
			'field_artdom_ab_principles',
			array_map(
				static function ( $p ) {
					return array( 'field_artdom_pr_title' => $p[0], 'field_artdom_pr_text' => $p[1] );
				},
				$data['ab_principles']
			),
			$page_id
		);
	}

	if ( ! get_field( 'ab_path', $page_id ) ) {
		update_field(
			'field_artdom_ab_path',
			array_map(
				static function ( $p ) {
					return array( 'field_artdom_pt_year' => $p[0], 'field_artdom_pt_title' => $p[1], 'field_artdom_pt_text' => $p[2] );
				},
				$data['ab_path']
			),
			$page_id
		);
	}

	if ( ! get_field( 'ab_team', $page_id ) ) {
		update_field(
			'field_artdom_ab_team',
			array_map(
				static function ( $p ) {
					return array( 'field_artdom_tm_name' => $p[0], 'field_artdom_tm_role' => $p[1], 'field_artdom_tm_note' => $p[2] );
				},
				$data['ab_team']
			),
			$page_id
		);
	}

	/* Длинный текст из содержимого страницы больше не нужен: он разложен по
	   блокам. Оставляем только раздел «Чем занимаемся», если он там был. */
	$post = get_post( $page_id );
	if ( $post && false !== mb_strpos( (string) $post->post_content, 'Как мы работаем' ) ) {
		wp_update_post( array( 'ID' => $page_id, 'post_content' => '' ) );
	}
}

/**
 * Набор демонстрационных снимков для галерей.
 *
 * Своих фотографий к статьям у компании пока нет, поэтому берём файлы темы —
 * те же, что у объектов. Смысл галереи здесь показать построение и работу
 * увеличения, а не выдать эти кадры за иллюстрации к тексту.
 */
function artdom_demo_gallery() {
	$out = array();
	foreach ( array( 'object.webp', 'garanty.webp', 'garanty-2.webp', 'garanty-3.webp', 'uslugi.webp' ) as $file ) {
		$id = artdom_demo_image( $file );
		if ( $id ) {
			$out[] = $id;
		}
	}
	return $out;
}
